/** Canonical Gauntlet battlefield-state derivation. Presentation-free and hook-free. */

import { collectStandingSitrepCombatants, SITREP_FACTIONS } from "../shared/sitrep-combatant-primitives.js";
import { controllerFromCounts } from "../shared/sitrep-control-primitives.js";
import { currentSitrepRound, sitrepRoundsRemaining } from "../shared/sitrep-round-primitives.js";
import { resolveConfiguredSitrepRegion, tokenInsideConfiguredSitrepRegion } from "../shared/sitrep-spatial-delegation.js";
import { gauntletControlWeight } from "./gauntlet-control-weight.js";

export function createEmptyGauntletState(combat, sitrep) {
  return {
    valid: false,
    currentRound: currentSitrepRound(combat, sitrep),
    roundsRemaining: sitrepRoundsRemaining(combat, sitrep),
    friendlyStanding: 0,
    hostileStanding: 0,
    friendlyInZone: 0,
    hostileInZone: 0,
    controller: "none",
    regionName: "Missing Region",
    immediateVictory: false,
    immediateReason: ""
  };
}

export function calculateGauntletState(combat, sitrep, spatialOperations) {
  const state = createEmptyGauntletState(combat, sitrep);
  if (!combat || !sitrep || sitrep.type !== "gauntlet") return state;

  const standingCombatants = collectStandingSitrepCombatants(combat, {
    controlWeightForActor: gauntletControlWeight
  });

  for (const entry of standingCombatants) {
    if (entry.faction === SITREP_FACTIONS.FRIENDLY) state.friendlyStanding += entry.controlWeight;
    if (entry.faction === SITREP_FACTIONS.HOSTILE) state.hostileStanding += entry.controlWeight;
  }

  const region = resolveConfiguredSitrepRegion(spatialOperations, combat, sitrep.regionId);
  if (!region) return state;

  state.valid = true;
  state.regionName = region.name || "Control Zone";

  for (const entry of standingCombatants) {
    if (!tokenInsideConfiguredSitrepRegion(spatialOperations, entry.token, region)) continue;
    if (entry.faction === SITREP_FACTIONS.FRIENDLY) state.friendlyInZone += entry.controlWeight;
    if (entry.faction === SITREP_FACTIONS.HOSTILE) state.hostileInZone += entry.controlWeight;
  }

  state.controller = controllerFromCounts(state.friendlyInZone, state.hostileInZone);

  if (sitrep.rules?.enemyElimination && state.hostileStanding === 0 && state.friendlyStanding > 0) {
    state.immediateVictory = true;
    state.immediateReason = "All hostile units have been defeated.";
  } else if (sitrep.rules?.unassailableControl && state.friendlyInZone > 0 && state.friendlyInZone > state.hostileStanding) {
    state.immediateVictory = true;
    state.immediateReason = "The allies already in the zone outnumber every surviving hostile unit.";
  }

  return state;
}

/** Canonical Gauntlet encounter transition semantics. No hooks, chat, or DOM ownership. */

import { readSitrepState, updateSitrepState } from "../state/sitrep-state-service.js";
import { calculateGauntletState } from "./gauntlet-state.js";

function resultIntent(status, reason) {
  return Object.freeze({
    kind: "sitrep-result",
    sitrepType: "gauntlet",
    status,
    reason
  });
}

export function deriveGauntletResolution(combat, sitrep, changes, spatialOperations) {
  if (!combat || !sitrep || sitrep.type !== "gauntlet" || !sitrep.active || sitrep.status !== "active") return null;

  const state = calculateGauntletState(combat, sitrep, spatialOperations);
  if (!state.valid) return null;

  if (state.immediateVictory) {
    return { status: "victory", reason: state.immediateReason, state };
  }

  const roundChanged = Object.prototype.hasOwnProperty.call(changes ?? {}, "round");
  if (!roundChanged) return null;

  const previousRound = Number(combat.previous?.round ?? 0);
  const finalRound = Number(sitrep.finalRound);
  const currentRound = Number(combat.round);
  const advancedPastFinalRound = currentRound > finalRound;
  const fallbackPastFinalRound = previousRound === finalRound && currentRound !== previousRound;
  if (!advancedPastFinalRound && !fallbackPastFinalRound) return null;

  const won = Boolean(
    sitrep.rules?.finalZoneControl &&
    state.friendlyInZone > state.hostileInZone &&
    state.friendlyInZone > 0
  );

  const reason = won
    ? `At the end of round ${sitrep.finalRound}, allied units controlled the zone ${state.friendlyInZone} to ${state.hostileInZone}.`
    : `At the end of round ${sitrep.finalRound}, allied units did not control the zone (${state.friendlyInZone} allied, ${state.hostileInZone} hostile).`;

  return { status: won ? "victory" : "defeat", reason, state };
}

export async function resolveGauntletEncounterUpdate(combat, changes = {}, spatialOperations) {
  const sitrep = readSitrepState(combat);
  const resolution = deriveGauntletResolution(combat, sitrep, changes, spatialOperations);
  if (!resolution) return Object.freeze({ changed: false, state: sitrep, outputIntent: null });

  const nextState = await updateSitrepState({
    status: resolution.status,
    resultReason: resolution.reason
  }, combat);

  return Object.freeze({
    changed: true,
    state: nextState,
    derivedState: resolution.state,
    outputIntent: resultIntent(resolution.status, resolution.reason)
  });
}

